// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/sandboxes", wrapper.ListSandboxes)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/sandboxes", wrapper.CreateSandbox)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/sandboxes/{sandboxID}", wrapper.DeleteSandbox)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/sandboxes/{sandboxID}", wrapper.GetSandbox)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/v1/sandboxes/{sandboxID}", wrapper.UpdateSandbox)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/sandboxes/{sandboxID}/app", wrapper.GetSandboxApp)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/system-templates", wrapper.ListSystemTemplates)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/templates", wrapper.ListTemplates)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/templates", wrapper.CreateTemplate)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/templates/{templateID}", wrapper.DeleteTemplate)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/templates/{templateID}", wrapper.GetTemplate)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/v1/templates/{templateID}", wrapper.UpdateTemplate)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/templates/{templateID}/builds", wrapper.CreateTemplateBuild)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/templates/{templateID}/builds/{buildID}", wrapper.GetTemplateBuild)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/templates/{templateID}/tags/{tag}", wrapper.DeleteTemplateTag)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/templates/{templateID}/tags/{tag}", wrapper.GetTemplateTag)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/v1/templates/{templateID}/tags/{tag}", wrapper.SetTemplateTag)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/templates/{templateID}/fork", wrapper.ForkTemplate)

	return m
}
